
import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Info, Brain, Heart, Sparkles, Ghost } from 'lucide-react';
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip";

export type GreysonItem = {
    score: 0 | 1 | 2;
    reasoning: string;
};

export type GreysonBreakdown = {
    cognitive: {
        time_distortion: GreysonItem;
        thought_speed: GreysonItem;
        life_review: GreysonItem;
        sudden_understanding: GreysonItem;
    };
    affective: {
        peace_pleasantness: GreysonItem;
        joy: GreysonItem;
        cosmic_unity: GreysonItem;
        brilliant_light: GreysonItem;
    };
    paranormal: {
        enhanced_senses: GreysonItem;
        esp: GreysonItem;
        precognition: GreysonItem;
        out_of_body: GreysonItem;
    };
    transcendental: {
        unearthly_world: GreysonItem;
        mystical_being: GreysonItem;
        spirits_deceased: GreysonItem;
        border_point_no_return: GreysonItem;
    };
};

interface GreysonScoreCardProps {
    totalScore: number;
    classification: string;
    breakdown: GreysonBreakdown;
}

// Helper to format key names (e.g., "time_distortion" -> "Time distortion")
const formatLabel = (key: string) => {
    return key
        .replace(/_/g, ' ')
        .replace(/^\w/, (c) => c.toUpperCase());
};

const getScoreColor = (score: number) => {
    if (score >= 20) return "text-purple-400"; // Deep
    if (score >= 13) return "text-blue-400";   // Moderate
    if (score >= 7) return "text-yellow-400";  // Mild
    return "text-gray-400"; // Not NDE
};

const CategorySection = ({
    title,
    icon: Icon,
    items
}: {
    title: string;
    icon: any;
    items: Record<string, GreysonItem>
}) => (
    <div className="space-y-3">
        <div className="flex items-center gap-2 text-sm font-semibold text-muted-foreground uppercase tracking-wider">
            <Icon className="w-4 h-4" />
            {title}
        </div>
        <div className="space-y-2">
            {Object.entries(items).map(([key, item]) => (
                <div key={key} className="flex justify-between items-center text-sm group">
                    <TooltipProvider>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <span className="text-foreground/80 cursor-help border-b border-dotted border-muted-foreground/30 hover:border-muted-foreground/60 transition-colors">
                                    {formatLabel(key)}
                                </span>
                            </TooltipTrigger>
                            <TooltipContent side="right" className="max-w-xs">
                                <p className="font-medium mb-1">{formatLabel(key)}</p>
                                <p className="text-xs text-muted-foreground">{item.reasoning}</p>
                            </TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                    <span className={`font-mono font-medium ${item.score > 0 ? 'text-primary' : 'text-muted-foreground/50'}`}>
                        {item.score}
                    </span>
                </div>
            ))}
        </div>
    </div>
);

export function GreysonScoreCard({ totalScore, classification, breakdown }: GreysonScoreCardProps) {
    if (!breakdown) return null;

    return (
        <Card className="border-2 border-primary/20 bg-background/50 backdrop-blur-sm">
            <CardHeader className="pb-4">
                <div className="flex justify-between items-start">
                    <div>
                        <CardTitle className="flex items-center gap-2 text-lg">
                            <Brain className="w-5 h-5 text-primary" />
                            Greyson NDE Scale
                            <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger>
                                        <Info className="w-4 h-4 text-muted-foreground hover:text-foreground transition-colors" />
                                    </TooltipTrigger>
                                    <TooltipContent className="max-w-sm">
                                        <p>The Greyson Scale is a validated scientific measure of NDE depth. It rates 16 items across 4 categories. A score of 7+ typically indicates a genuine NDE. Maximum score is 32.</p>
                                    </TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        </CardTitle>
                        <div className="mt-1">
                            <Badge variant="outline" className="text-xs font-normal">
                                AI Estimated
                            </Badge>
                        </div>
                    </div>
                </div>

                <div className="mt-6 flex flex-col items-center justify-center text-center">
                    <div className={`text-6xl font-bold ${getScoreColor(totalScore)}`}>
                        {totalScore}
                    </div>
                    <div className="text-sm text-muted-foreground mt-1">out of 32</div>
                    <Badge className={`mt-3 ${getScoreColor(totalScore)} bg-primary/10 hover:bg-primary/20 border-0`}>
                        {classification || "N/A"}
                    </Badge>
                </div>
            </CardHeader>

            <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-8 mt-4">
                    <CategorySection title="Cognitive" icon={Brain} items={breakdown.cognitive} />
                    <CategorySection title="Affective" icon={Heart} items={breakdown.affective} />
                    <CategorySection title="Paranormal" icon={Ghost} items={breakdown.paranormal} />
                    <CategorySection title="Transcendental" icon={Sparkles} items={breakdown.transcendental} />
                </div>
            </CardContent>
        </Card>
    );
}
